using System;
using System.Net.Http;
using System.Threading.Tasks;

public class ApiClient
{
    // The async keyword enables the await operator inside this method
    // Task<string> means: this is an async operation that will return a string
    public async Task<string> FetchWeatherAsync(string city)
    {
        // HttpClient is intended to be reused; 'using' here is for demonstration
        using var client = new HttpClient();

        // await pauses THIS method only — the calling thread is NOT blocked
        // Execution returns to the caller until the HTTP response arrives
        string url = $"https://api.example.com/weather?city={Uri.EscapeDataString(city)}";
        string json = await client.GetStringAsync(url);

        // When the response arrives, execution resumes here on a thread-pool thread
        return json; // Compiler wraps this in a Task<string> automatically
    }
}

public class AsyncDemo
{
    public static async Task Main()
    {
        ApiClient client = new ApiClient();

        // Call the async method — we must await it
        string weatherData = await client.FetchWeatherAsync("London");

        Console.WriteLine($"Weather data received ({weatherData.Length} chars)");
        Console.WriteLine(weatherData);
    }
}

using System;
using System.Diagnostics;
using System.Threading.Tasks;

public class TaskDemo
{
    // Task — no return value
    public async Task LogAsync(string message)
    {
        await Task.Delay(500); // Simulates async I/O
        Console.WriteLine($"[Log] {message}");
    }

    // Task<TResult> — returns a value
    public async Task<int> ComputeSumAsync(int a, int b)
    {
        await Task.Delay(200); // Simulate work
        return a + b;
    }

    public static async Task Main()
    {
        TaskDemo demo = new TaskDemo();

        // Run three tasks concurrently, not sequentially
n        Task task1 = demo.LogAsync("Starting...");
        Task<int> task2 = demo.ComputeSumAsync(10, 20);
        Task<int> task3 = demo.ComputeSumAsync(5, 15);

        // Wait for all to complete — throws if any faulted
        await Task.WhenAll(task1, task2, task3);

        // Retrieve results
        int sum2 = task2.Result; // 30
        int sum3 = task3.Result; // 20
        Console.WriteLine($"Results: {sum2}, {sum3}");

        // WhenAny — get the first completed task
        Task<int> fastest = await Task.WhenAny(task2, task3);
        Console.WriteLine($"First to finish returned: {fastest.Result}");

        // Measure elapsed wall-clock time
        Stopwatch sw = Stopwatch.StartNew();
n        await Task.WhenAll(
            Task.Delay(1000),
            Task.Delay(1000),
            Task.Delay(1000)
        );
        sw.Stop();
        Console.WriteLine($"3 concurrent delays took {sw.ElapsedMilliseconds}ms (not 3000!)");
    }
}

using System;
using System.Threading.Tasks;

public class ExceptionPropagation
{
    public static async Task<string> RiskyOperationAsync(bool shouldFail)
    {
        await Task.Delay(100);

        if (shouldFail)
        {
            // Exception is captured inside the returned Task, not thrown now
            throw new InvalidOperationException("Something went wrong!");
        }

        return "Success!";
    }

    public static async Task Main()
    {
        try
        {
            // Exception is re-thrown HERE, when we await
            string result = await RiskyOperationAsync(true);
            Console.WriteLine(result);
        }
        catch (InvalidOperationException ex)
        {
            Console.WriteLine($"Caught: {ex.Message}");
        }

        // Without await, the exception is stored — unobserved Task fault
        Task<string> unobserved = RiskyOperationAsync(true);
        // Accessing .Result would also re-throw the exception
        try
        {
            string val = unobserved.Result;
        }
        catch (AggregateException ex)
        {
            Console.WriteLine($"Via .Result: {ex.InnerException?.Message}");
        }
    }
}

using System;
using System.Net.Http;
using System.Threading.Tasks;

public class ParallelApiDemo
{
    static readonly HttpClient client = new HttpClient();

    static async Task<string> FetchJsonAsync(string url)
    {
        return await client.GetStringAsync(url);
    }

    public static async Task Main()
    {
        string[] urls =
        {
            "https://api.example.com/users",
            "https://api.example.com/posts",
            "https://api.example.com/comments"
        };

        // Start all requests immediately (they run in parallel)
        Task<string>[] tasks = new Task<string>[urls.Length];
        for (int i = 0; i < urls.Length; i++)
        {
            tasks[i] = FetchJsonAsync(urls[i]);
        }

        // Await all at once — total time ≈ slowest single request, not the sum
        string[] results = await Task.WhenAll(tasks);

        for (int i = 0; i < results.Length; i++)
        {
            Console.WriteLine($"URL {i + 1}: {results[i].Length} chars");
        }
    }
}
